apiParameters:
{
  "query": {
    "type": "array",
    "format": [
      "phenotype",
      "region"
    ],
    "index": "associations"
  },
  "parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype",
      "type": "list",
      "values": [
        "BMI_GIANT",
"HEIGHT_GIANT",
"WHRadjBMI_female_GIANT",
"WHRadjBMI_GIANT",
"WHRadjBMI_male_GIANT",
"WHRU_female_GIANT",
"WHRU_GIANT",
"WHRU_male_GIANT"
      ]
    },
    {
      "parameter": "region",
      "label": "Region (gene +-500K)",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true",
      "expand region": "true",
      "expand region by": 1000000
    }
  ]
}

dataComparisonFormat:
{
"key field":"Variant ID",
