visualizerConfiguration:
{
  "type": "giant gem package",
  "viewers": [
    "region plot",
    "genes plot",
    "credible sets plot",
    "annotations plot v2",
    "biosamples plot",
    "gene-links plot"
  ],
  "pkg id": "testPkg",
  "region viewer": {
    "x axis field": "Position",
    "y axis field": "-log10(P-Value)",
    "render by": "Variant ID",
    "y axis label": "-Log10(p-value)",
    "x axis label": "Chromosome",
    "hover content": [
      "P-Value",
      "Beta"
    ],
    "height": 120,
    "star key": "Variant ID",
    "ld server": {
      "pos": "Position",
      "ref": "ref",
      "alt": "alt",
      "ref variant field": "Variant ID",
      "populations field": "Ancestry",
      "populations type": "fixed",
      "fixed population": "ALL",
      "populations": {
        "ALL": "ALL"
      }
    }
  },
  "credible sets viewer": {
    "note": "The conponent for this plot is custom. Data point is hardcoded.",
    "credible sets server": "https://giant.hugeampkpnbi.org/api/bio",
    "phenotype parameter": "phenotype",
    "region parameter": "region",
    "x axis field": "position",
    "y axis field": "posteriorProbability",
    "hover content": [
      "posteriorProbability",
      "credibleSetId"
    ],
    "render by": "Variant ID",
    "data convert": [
      {
        "type": "join multi",
        "field name": "Variant ID",
        "fields to join": [
          "chromosome",
          "position",
          "reference",
          "alt"
        ],
        "join by": [
          ":",
          "_",
          "/"
        ]
      },
      {
        "type": "raw",
        "field name": "position",
        "raw field": "position"
      },
      {
        "type": "raw",
        "field name": "posteriorProbability",
        "raw field": "posteriorProbability"
      },
      {
        "type": "raw",
        "field name": "credibleSetId",
        "raw field": "credibleSetId"
      },
      {
        "type": "raw",
        "field name": "phenotype",
        "raw field": "phenotype"
      }
    ]
  },
  "annotations viewer": {
    "annotations server": "KP BioIndex",
    "phenotype parameter": "phenotype",
    "phenotype match": {
      "BMI_GIANT": "BMI",
      "HEIGHT_GIANT": "HEIGHT",
      "WHRadjBMI_GIANT": "WHRadjBMI",
      "WHRU_GIANT": "WHR"
    },
    "star key": {
      "key": "Variant ID",
      "position": "Position"
    }
  },
  "biosamples viewer": {
    "biosamples server": "KP BioIndex",
    "phenotype parameter": "phenotype",
    "phenotype match": {
      "BMI_GIANT": "BMI",
      "HEIGHT_GIANT": "HEIGHT",
      "WHRadjBMI_GIANT": "WHRadjBMI",
      "WHRU_GIANT": "WHR"
    },
    "overlapping regions": "true",
    "with annotations viewer": "true",
    "ui table legend": "Table is sorted by fold enrichment (SNPs/expectedSNPs) across annotations.",
    "star key": {
      "key": "Variant ID",
      "position": "Position"
    }
  },
  "gene-links viewer": {
    "with annotations viewer": "true",
    "gene links server": "KP BioIndex",
    "phenotype parameter": "phenotype",
    "phenotype match": {
      "BMI_GIANT": "BMI",
      "HEIGHT_GIANT": "HEIGHT",
      "WHRadjBMI_GIANT": "WHRadjBMI",
      "WHRU_GIANT": "WHR"
    },
    "region parameter": "region",
    "overlapping regions": "true",
    "global enrichment plot labels": {
      "x axis": "",
      "y axis": ""
    },
    "star key": {
      "key": "Variant ID",
      "position": "Position"
    }
  },
  "genes track": {
    "input type": "dynamic",
    "dynamic parameter": "region"
  },
  "zoom": "true"
}
